INSERT IGNORE INTO course_experts (full_name, slug, credentials, experience) VALUES ('Кишиневская Марина Александровна', 'kishinevskaya-marina-aleksandrovna', 'Учитель-логопед высшей кв. категории, дефектолог, клинический психолог. Преподаватель кафедры педагогики и психологии университета им. С.Ю. Витте. Награждена грамотой Департамента образования города Москвы за личные заслуги, способствующие реализации перспективных направлений в обучении и воспитании подрастающего поколения. Автор книг и пособий.', '21 год');
INSERT IGNORE INTO course_experts (full_name, slug, credentials, experience) VALUES ('Белых Ксения Константиновна', 'belyh-kseniya-konstantinovna', 'Специалист-практик с опытом работы по специальности 8 лет. Полуфиналист конкурса «Учитель-дефектолог года» в г. Москва 2024. Организатор межрегионального профориентационного форума «Хочу, знаю, действую» для лиц с ограниченными возможностями здоровья и инвалидностью 2025 г. Победитель конкурса на научную стажировку в Институте коррекционной педагогики 2024 г. и 2025 г. Эксперт РООИ Перспектива с 2023 года (проведение вебинаров и помощь в организации мероприятий). Эксперт программы «Утро в большом городе» интернет-радио «Вечерний проспект» в 2025 г.', '8 лет');
INSERT IGNORE INTO course_experts (full_name, slug, credentials, experience) VALUES ('Дуванов Петр Петрович', 'duvanov-petr-petrovich', 'Преподаватель основ военной подготовки в Пермском суворовском училище.', '17 лет');
INSERT IGNORE INTO course_experts (full_name, slug, credentials, experience) VALUES ('Колесниченко Любовь Ивановна', 'kolesnichenko-lyubov-ivanovna', 'победитель конкурса «Лучшие учителя России» национального проекта «Образование», награждена премией Президента РФ, педагог СОШ №9 им. А.С. Пушкина с углубленным изучением предметов физико-математического цикла.', NULL);
