INSERT IGNORE INTO course_experts (full_name, slug, credentials, experience) VALUES ('Лысова Ольга Юрьевна', 'lysova-olga-yurevna', 'Практикующий логопед, учитель-дефектолог, методолог. Руководитель и главный специалист «Центра развития речи Ольги Лысовой».', '6 лет');
