INSERT IGNORE INTO course_experts (full_name, slug, credentials, experience) VALUES ('Шинакова Светлана Викторовна', 'shinakova-svetlana-viktorovna', 'Председатель учебно-методического совета Колледжа экономики, управления и права ДГТУ.', '31 год');
INSERT IGNORE INTO course_experts (full_name, slug, credentials, experience) VALUES ('Рюмина Юлия Евгеньевна', 'ryumina-yuliya-evgenevna', 'Учитель начальных классов, учитель-дефектолог (тифлопедагог). Победитель V регионального Фестиваля мастер-классов учителей-дефектологов-2025.', '15 лет');
INSERT IGNORE INTO course_experts (full_name, slug, credentials, experience) VALUES ('Букина Виктория Юрьевна', 'bukina-viktoriya-yurevna', 'Логопед-дефектолог онлайн. Нейропсихолог. Монтессори педагог. Радиоведущая, актриса дубляжа. Руководитель онлайн школы RepetitorVsem.', NULL);
INSERT IGNORE INTO course_experts (full_name, slug, credentials, experience) VALUES ('Ишметова Марина Александровна', 'ishmetova-marina-aleksandrovna', 'Эксперт в области работы с неговорящими детьми. Активирует речевые умения у детей с 2,5 лет по немецкой методике VED. Организатор и спикер конференций для логопедов.', '23 года');
INSERT IGNORE INTO course_experts (full_name, slug, credentials, experience) VALUES ('Разгонюк Ольга Сергеевна', 'razgonyuk-olga-sergeevna', 'Практикующий дошкольный логопед высшей квалификационной категории со стажем более 18 лет. Специалист по логопедическому массажу, логопедическому тейпированию, миофункциональной коррекции. Автор блога по логопедии в социальных сетях.', '18 лет');
INSERT IGNORE INTO course_experts (full_name, slug, credentials, experience) VALUES ('Шутова Наталья Геннадьевна', 'shutova-natalya-gennadevna', 'Логопед, дефектолог, специалист по заиканию. Имеет 2 патента на метод коррекции заикания «Системная комплексная логоритмика». Основатель и руководитель центра логопедии и нейропсихологии, онлайн-школы. Проводит очные лекции по заиканию по России и странам СНГ. Автор публикаций в Альманахе «Мир специальной педагогики и психологии.', '27 лет');
INSERT IGNORE INTO course_experts (full_name, slug, credentials, experience) VALUES ('Ребковец Евгения Андреевна', 'rebkovets-evgeniya-andreevna', 'Логопед, дефектолог, основатель ассоциации логопедов в СПб, авто блога по логопедии «Бережный логопед».', NULL);
INSERT IGNORE INTO courses (title, slug, description, target_audience_text, course_group, hours, program_type, learning_format, price, modules_json, outcomes_json, federal_registry_info, is_active, display_order) VALUES ('Специальное (дефектологическое) образование. Работа учителя-дефектолога с детьми с задержкой психического развития дошкольного и школьного возрастов (профиль: задержка психического развития)', 'spetsialnoe-defektologicheskoe-obrazovanie-rabota-uchitelya-defektologa-s-detmi-s-zaderzhkoy-psihicheskogo-razvitiya-doshkolnogo-i-shkolnogo-vozrastov-profil-zaderzhka-psihicheskogo-razvitiy', 'Вы станете востребованным дефектологом, владеющим современными методами диагностики и коррекции ЗПР у детей дошкольного и школьного возраста.', 'Дефектолог\nКурс предназначен как для начинающих дефектологов, желающих получить актуальные знания и навыки для уверенного старта в профессии, так и опытным специалистам, стремящимся обновить свой инструментарий методами нейронаук и доказательной педагогики для работы с детьми с ЗПР.', 'Специальное образование', 520, 'pp', 'заочная с применением дистанционных образовательных технологий', 25800, '[{"number": 1, "title": "Медико-биологические основы дефектологии"}, {"number": 2, "title": "Основы нейропсихологии в работе учителя-дефектолога"}, {"number": 3, "title": "Основы специальной педагогики и психологии"}, {"number": 4, "title": "Возрастная педагогика и психология"}, {"number": 5, "title": "Основы логопедии"}, {"number": 6, "title": "Основы патопсихологии"}, {"number": 7, "title": "Инклюзивное и интегративное образование"}, {"number": 8, "title": "Работа с детьми с ЗПР"}, {"number": 9, "title": "Работа с детьми с комплексными расстройствами"}, {"number": 10, "title": "Взаимодействие учителя-дефектолога с родителями"}, {"number": 11, "title": "Работа учителя-дефектолога в образовательных учреждениях"}, {"number": 12, "title": "Взаимодействие специалистов по сопровождению ребенка с ОВЗ, ребенка-инвалида"}, {"number": 13, "title": "Профилактика синдрома эмоционального выгорания"}, {"number": 14, "title": "Цифровые компетенции современного педагога"}]', '{"knowledge": [], "skills": ["Детский сад и школа: выпускник сможет реализовывать адаптированные программы (ФАОП), проводить диагностику и выстраивать инклюзивное обучение детей с ЗПР в рамках государственных образовательных учреждений.\\n\\nРеабилитационные центры и ПМПК: специалист готов к работе в мультидисциплинарной команде, где будет проводить сложную дифференциальную диагностику и координировать сопровождение детей с тяжелыми нарушениями.\\n\\nЧастная практика: программа дает инструменты для ведения индивидуального приема, разработки авторских коррекционных методик и профессионального консультирования родителей по вопросам развития ребенка."], "abilities": []}', NULL, 1, @start_order + 1);
INSERT IGNORE INTO courses (title, slug, description, target_audience_text, course_group, hours, program_type, learning_format, price, modules_json, outcomes_json, federal_registry_info, is_active, display_order) VALUES ('Педагогическое образование. Основы безопасности и защиты Родины в условиях реализации ФГОС ООО, СОО', 'pedagogicheskoe-obrazovanie-osnovy-bezopasnosti-i-zaschity-rodiny-v-usloviyah-realizatsii-fgos-ooo-soo', 'Программа позволит по-новому использовать навыки преподавания предмета «Основы безопасности и защита Родины» в образовательных организациях, использовать современные методы и технологии обучения.', NULL, 'Школа', 520, 'pp', 'заочная с применением дистанционных образовательных технологий', 47700, '[{"number": 1, "title": "Педагогика как наука и область практической деятельности. Общие основы педагогического процесса"}, {"number": 2, "title": "Воспитательный процесс. Особенности содержания и организации воспитательного процесса на современном этапе"}, {"number": 3, "title": "Теория обучения (дидактика). Особенности содержания и организации дидактического процесса на современном этапе"}, {"number": 4, "title": "Обновленный Федеральный государственный образовательный стандарт основного общего образования"}, {"number": 5, "title": "Основная образовательная программа основного и среднего общего образования"}, {"number": 6, "title": "Система оценки достижения планируемых результатов освоения основной образовательной программы ООО"}, {"number": 7, "title": "Формирование и оценка личностных результатов в соответствии с требованиями обновленного ФГОС ООО"}, {"number": 8, "title": "Формирование и оценка метапредметных результатов в соответствии с требованиями обновленного ФГОС ООО"}, {"number": 9, "title": "Обновленный Федеральный государственный образовательный стандарт среднего общего образования"}, {"number": 10, "title": "Основная образовательная программа среднего общего образования"}, {"number": 11, "title": "Оценка качества освоения основной образовательной программы среднего общего образования"}, {"number": 12, "title": "Формирование и оценка личностных результатов в соответствии с требованиями обновленного ФГОС"}, {"number": 13, "title": "Формирование и оценка метапредметных результатов в соответствии с требованиями обновленного ФГОС"}, {"number": 14, "title": "Содержание и организация обучения предмета «Основы безопасности и защиты Родины» в условиях реализации обновленного ФГОС"}, {"number": 15, "title": "Теория и методика преподавания предмета «Основы безопасности и защиты Родины» в школе"}]', '{"knowledge": [], "skills": ["Работа преподавателем ОБЖ и защиты Родины в школе, коллеже или техникуме: вы будете проводить уроки по основам безопасности и военной подготовке, организовывать учебные сборы и военно-патриотические мероприятия, обучать правилам безопасного поведения, основам первой помощи, действиям в чрезвычайных ситуациях, развивать у учеников чувство ответственности и готовность к защите Родины. В сферу вашей деятельности также будет выходить методическая работа и поддержка продуктивного взаимодействия с родителями, коллегами и администрацией.\\n\\nРабота в государственных и частных учреждениях дополнительного образования: вы сможете разрабатывать и внедрять программы дополнительного образования, руководить военно-патриотическими детскими и молодежными объединениями, организовывать соревнования, учебные сборы и патриотические мероприятия."], "abilities": []}', NULL, 1, @start_order + 2);
INSERT IGNORE INTO courses (title, slug, description, target_audience_text, course_group, hours, program_type, learning_format, price, modules_json, outcomes_json, federal_registry_info, is_active, display_order) VALUES ('Педагогическое образование. Физика в условиях реализации ФГОС ООО, СОО', 'pedagogicheskoe-obrazovanie-fizika-v-usloviyah-realizatsii-fgos-ooo-soo', 'Программа для учителей физики научит грамотно планировать и проводить учебные занятия, разрабатывать рабочую программу по предмету, а также применять современные образовательные технологии.', NULL, 'Школа', 520, 'pp', 'заочная с применением дистанционных образовательных технологий', 47700, '[{"number": 1, "title": "Педагогические технологии в современной школе"}, {"number": 2, "title": "Введение и реализация обновленного ФГОС ООО в общеобразовательных организациях"}, {"number": 3, "title": "Введение и реализация обновленного ФГОС среднего общего образования в общеобразовательных организациях"}, {"number": 4, "title": "Содержание и организация обучения информатике в условиях реализации ФГОС"}]', '{"knowledge": [], "skills": ["Работа учителем физики в школе: вы будете вести уроки физики, организовывать внеурочную деятельность — научные клубы, экспериментальные лаборатории и проекты, участвовать в методической деятельности — разрабатывать программы, участвовать в педсоветах и конкурсах, взаимодействовать с родителями учеников и коллегами.\\n\\nРабота в государственных и частных учреждениях дополнительного образования: вы сможете создавать авторские курсы по физике и смежным направлениям, вести занятия в тематических кружках, помогать развиваться талантливым ученикам и вдохновлять их на открытия.\\n\\nЧастная практика (репетиторство): в сферу вашей деятельности будет входить подготовка учеников к итоговой аттестации по физике (ВПР, ОГЭ, ЕГЭ) и олимпиадам, помощь с углубленным изучением предмета и разбором сложных тем."], "abilities": []}', NULL, 1, @start_order + 3);
INSERT IGNORE INTO courses (title, slug, description, target_audience_text, course_group, hours, program_type, learning_format, price, modules_json, outcomes_json, federal_registry_info, is_active, display_order) VALUES ('Воспитатель логопедической группы. Педагогическая и коррекционно-развивающая помощь детям с нарушениями речи в условиях реализации ФГОС ДО', 'vospitatel-logopedicheskoy-gruppy-pedagogicheskaya-i-korrektsionno-razvivayuschaya-pomosch-detyam-s-narusheniyami-rechi-v-usloviyah-realizatsii-fgos-do', 'Курс для воспитателей, работающих с речевыми нарушениями у детей дошкольного возраста.', NULL, 'Дошкольное образование', 520, 'pp', 'заочная с применением дистанционных образовательных технологий', 23850, '[{"number": 1, "title": "Федеральный государственный образовательный стандарт дошкольного образования"}, {"number": 2, "title": "Основы дошкольной педагогики и психологии"}, {"number": 3, "title": "Планируемые результаты дошкольного образования"}, {"number": 4, "title": "Образовательная деятельность в дошкольной образовательной организации"}, {"number": 5, "title": "Организация развивающей предметно-пространственной среды и психолого-педагогические условия"}, {"number": 6, "title": "Основы логопедии"}, {"number": 7, "title": "Психолого-педагогическая диагностика нарушений речевого развития детей"}, {"number": 8, "title": "Нарушения устной речи: причины и особенности проявления"}, {"number": 9, "title": "Традиционные логопедические технологии"}, {"number": 10, "title": "Нетрадиционные (современные) логопедические технологии"}, {"number": 11, "title": "Логопедическая работа в ДО"}, {"number": 12, "title": "Взаимодействие логопеда и родителей в процессе организации коррекционно-развивающего обучения детей"}]', '{"knowledge": [], "skills": ["Работа воспитателем логопедической группы в государственном или частном ДОУ: вы будете сопровождать детей с речевыми особенностями, создавать для них адаптированную образовательную среду, помогать в развитии коммуникации, памяти, внимания и мышления. Вашей задачей будет организация развивающих и коррекционных занятий по рекомендациям логопеда и создание благоприятной атмосферы для успешного обучения и достижения результатов."], "abilities": []}', NULL, 1, @start_order + 4);
INSERT IGNORE INTO courses (title, slug, description, target_audience_text, course_group, hours, program_type, learning_format, price, modules_json, outcomes_json, federal_registry_info, is_active, display_order) VALUES ('Педагогическое образование. Педагог-организатор', 'pedagogicheskoe-obrazovanie-pedagog-organizator', 'Программа позволит качественно планировать и организовывать культурную и досуговую деятельность учеников образовательных учреждений.', NULL, 'Школа', 252, 'pp', 'заочная с применением дистанционных образовательных технологий', 36300, '[{"number": 1, "title": "Педагогика как наука и область практической деятельности. Общие основы педагогического процесса"}, {"number": 2, "title": "Воспитательный процесс. Особенности содержания и организации воспитательного процесса на современном этапе"}, {"number": 3, "title": "Теория обучения (дидактика). Особенности содержания и организации дидактического процесса на современном этапе"}, {"number": 4, "title": "Организация профессиональной деятельности педагога-организатора"}, {"number": 5, "title": "Содержание, методика и организация досуговой деятельности учащихся (занятий кружков, секций, студий, клубных объединений)"}, {"number": 6, "title": "Содержание, методика и организация культурно-массовых мероприятий"}, {"number": 7, "title": "Содержание, методика и организация оздоровительно-спортивной деятельности"}, {"number": 8, "title": "Содержание, методика и организация туристско-краеведческой деятельности"}]', '{"knowledge": [], "skills": ["Работа педагогом-организатором в школах, центрах творчества и лагерях: вы будете организовывать мероприятия — от школьных праздников до волонтёрских акций, развивать школьное самоуправление, устраивать познавательные экскурсии и тематические недели.\\n\\nРабота event-менеджером в сфере образования: сможете организовывать детские и молодёжные мероприятия, квесты и образовательные фестивали, разрабатывать собственные проекты для детей и подростков. Это профессия для тех, кто умеет превращать обычные дни в яркие события и делать обучение увлекательным, а отдых продуктивным."], "abilities": []}', NULL, 1, @start_order + 5);
INSERT IGNORE INTO courses (title, slug, description, target_audience_text, course_group, hours, program_type, learning_format, price, modules_json, outcomes_json, federal_registry_info, is_active, display_order) VALUES ('Специальное (дефектологическое) образование. Работа учителя-дефектолога с детьми с ОВЗ дошкольного и школьного возрастов', 'spetsialnoe-defektologicheskoe-obrazovanie-rabota-uchitelya-defektologa-s-detmi-s-ovz-doshkolnogo-i-shkolnogo-vozrastov', 'Курс для тех, кто хочет стать дефектологом, который понимает причины и механику нарушений, а также умеет выстраивать коррекционную работы с самыми часто встречающимися нозологиями: ЗПР (задержка психического развития), ИН (интеллектуальные нарушения), РАС (расстройства аутистического спектра), ТМНР (тяжелые множественные нарушения развития).', NULL, 'Дошкольное образование', 1180, 'pp', 'заочная с применением дистанционных образовательных технологий', 33100, '[{"number": 1, "title": "Медико-биологические основы дефектологии"}, {"number": 2, "title": "Основы нейропсихологии в работе учителя-дефектолога"}, {"number": 3, "title": "Основы специальной педагогики и психологии"}, {"number": 4, "title": "Возрастная педагогика и психология"}, {"number": 5, "title": "Клинические основы психофизических расстройств у детей дошкольного и школьного возраста"}, {"number": 6, "title": "Основы речевого развития детей с ОВЗ (основы логопедии)"}, {"number": 7, "title": "Основы патопсихологии"}, {"number": 8, "title": "Инклюзивное и интегративное образование"}, {"number": 9, "title": "Работа с детьми с ЗПР"}, {"number": 10, "title": "Работа с детьми с ИН (УО)"}, {"number": 11, "title": "Работа с детьми с РАС"}, {"number": 12, "title": "Работа с детьми с ТМНР"}, {"number": 13, "title": "Взаимодействие специалистов по сопровождению ребенка с ОВЗ, ребенка-инвалида"}, {"number": 14, "title": "Цифровые компетенции современного педагога"}]', '{"knowledge": [], "skills": ["Возможность работать в государственных учреждениях учителем-дефектологом, таких как: детский сад и школа, а также работать частным образом."], "abilities": []}', NULL, 1, @start_order + 6);
INSERT IGNORE INTO courses (title, slug, description, target_audience_text, course_group, hours, program_type, learning_format, price, modules_json, outcomes_json, federal_registry_info, is_active, display_order) VALUES ('Педагогическое образование. Педагог-библиотекарь в современном образовательном пространстве', 'pedagogicheskoe-obrazovanie-pedagog-bibliotekar-v-sovremennom-obrazovatelnom-prostranstve', 'Программа для тех, кто желает планировать и организовывать информационно-библиографическое сопровождение учебного и воспитательного процессов, помогать учащимся и преподавателям в самообразовании.', NULL, 'Школа', 520, 'pp', 'заочная с применением дистанционных образовательных технологий', 36300, '[{"number": 1, "title": "Основы педагогики и психологии"}, {"number": 2, "title": "Цифровая трансформация: создание и развитие современного ИБЦ"}, {"number": 3, "title": "Содержание и организация библиотечно-педагогической деятельности"}, {"number": 4, "title": "Развитие читательской грамотности и организация событий в школьной библиотеке"}, {"number": 5, "title": "Безопасность образовательной среды"}, {"number": 6, "title": "Цифровые компетенции современного педагога"}]', '{"knowledge": [], "skills": ["Работа педагогом-библиотекарем в образовательных учреждениях: вы будете управлять библиотечным фондом школы, колледжа или вуза, сможете реализовать себя как организатор просветительских мероприятий, литературных клубов, квизов и встреч с авторами — и таким образом превращать библиотеку в современный образовательный центр.\\n\\nВ сфере частной практики для вас открыто развитие в цифровом пространстве: создание медиатек, ведение книжных блогов и подкастов для учащихся, разработка или редактирование образовательного контента и учебных материалов, сотрудничество с онлайн-платформами, консультирование издательств по учебной литературе."], "abilities": []}', NULL, 1, @start_order + 7);
INSERT IGNORE INTO courses (title, slug, description, target_audience_text, course_group, hours, program_type, learning_format, price, modules_json, outcomes_json, federal_registry_info, is_active, display_order) VALUES ('Специальное (дефектологическое) образование. Работа учителя-дефектолога с детьми с нарушениями слуха дошкольного и школьного возрастов (профиль: нарушения слуха)', 'spetsialnoe-defektologicheskoe-obrazovanie-rabota-uchitelya-defektologa-s-detmi-s-narusheniyami-sluha-doshkolnogo-i-shkolnogo-vozrastov-profil-narusheniya-sluha', 'Вы станете востребованным дефектологом, владеющим современными методами диагностики и коррекции психических процессов у детей с нарушением слуха дошкольного и школьного возраста.', 'Дефектолог\nКурс предназначен как для начинающих дефектологов, желающих получить актуальные знания и навыки для уверенного старта в профессии, так и опытным специалистам, стремящимся обновить свой инструментарий методами нейронаук и доказательной педагогики для работы с детьми с нарушениями слуха.', 'Дошкольное образование', 520, 'pp', 'заочная с применением дистанционных образовательных технологий', 25800, '[{"number": 1, "title": "Медико-биологические основы дефектологии"}, {"number": 2, "title": "Основы нейропсихологии в работе учителя-дефектолога"}, {"number": 3, "title": "Основы специальной педагогики и психологии"}, {"number": 4, "title": "Возрастная педагогика и психология"}, {"number": 5, "title": "Основы логопедии"}, {"number": 6, "title": "Основы патопсихологии"}, {"number": 7, "title": "Инклюзивное и интегративное образование"}, {"number": 8, "title": "Работа с детьми с нарушением слуха"}, {"number": 9, "title": "Работа с детьми с комплексными расстройствами"}, {"number": 10, "title": "Взаимодействие учителя-дефектолога с родителями"}, {"number": 11, "title": "Работа учителя-дефектолога в образовательных учреждениях"}, {"number": 12, "title": "Взаимодействие специалистов по сопровождению ребенка с ОВЗ, ребенка-инвалида"}, {"number": 13, "title": "Профилактика синдрома эмоционального выгорания"}, {"number": 14, "title": "Цифровые компетенции современного педагога"}]', '{"knowledge": [], "skills": ["Детский сад и школа: выпускник сможет реализовывать адаптированные программы (ФАОП), проводить диагностику и выстраивать инклюзивное обучение детей с ЗПР в рамках государственных образовательных учреждений.\\n\\nРеабилитационные центры и ПМПК: специалист готов к работе в мультидисциплинарной команде, где будет проводить сложную дифференциальную диагностику и координировать сопровождение детей с тяжелыми нарушениями.\\n\\nЧастная практика: программа дает инструменты для ведения индивидуального приема, разработки авторских коррекционных методик и профессионального консультирования родителей по вопросам развития ребенка."], "abilities": []}', NULL, 1, @start_order + 8);
INSERT IGNORE INTO courses (title, slug, description, target_audience_text, course_group, hours, program_type, learning_format, price, modules_json, outcomes_json, federal_registry_info, is_active, display_order) VALUES ('Специальное (дефектологическое) образование. Работа учителя-дефектолога с детьми с нарушениями опорно-двигательного аппарата дошкольного и школьного возрастов (профиль: нарушения опорно-двигательного аппарата)', 'spetsialnoe-defektologicheskoe-obrazovanie-rabota-uchitelya-defektologa-s-detmi-s-narusheniyami-oporno-dvigatelnogo-apparata-doshkolnogo-i-shkolnogo-vozrastov-profil-narusheniya-oporno-dviga', 'Вы станете востребованным дефектологом, владеющим современными методами диагностики и коррекции нарушений развития у детей с НОДА дошкольного и школьного возраста.', 'Дефектологи\nДля начинающих дефектологов, желающих получить актуальные знания и навыки для уверенного старта в профессии. Для опытных специалистов, стремящихся обновить свой инструментарий методами нейронаук и доказательной педагогики для работы с детьми с НОДА.', 'Дошкольное образование', 520, 'pp', 'заочная с применением дистанционных образовательных технологий', 25800, '[{"number": 1, "title": "Медико-биологические основы дефектологии"}, {"number": 2, "title": "Основы нейропсихологии в работе учителя-дефектолога"}, {"number": 3, "title": "Основы специальной педагогики и психологии"}, {"number": 4, "title": "Возрастная педагогика и психология"}, {"number": 5, "title": "Основы логопедии"}, {"number": 6, "title": "Основы патопсихологии"}, {"number": 7, "title": "Инклюзивное и интегративное образование"}, {"number": 8, "title": "Работа с детьми с НОДА"}, {"number": 9, "title": "Работа с детьми с комплексными расстройствами"}, {"number": 10, "title": "Взаимодействие учителя-дефектолога с родителями"}, {"number": 11, "title": "Работа учителя-дефектолога в образовательных учреждениях"}, {"number": 12, "title": "Взаимодействие специалистов по сопровождению ребенка с ОВЗ, ребенка-инвалида"}, {"number": 13, "title": "Профилактика синдрома эмоционального выгорания"}, {"number": 14, "title": "Цифровые компетенции современного педагога"}]', '{"knowledge": [], "skills": ["Детский сад и школа: выпускник сможет реализовывать адаптированные программы (ФАОП), проводить диагностику и выстраивать инклюзивное обучение детей с НОДА в рамках государственных образовательных учреждений.\\n\\nРеабилитационные центры и ПМПК: специалист готов к работе в мультидисциплинарной команде, где будет проводить сложную дифференциальную диагностику и координировать сопровождение детей с тяжелыми нарушениями.\\n\\nЧастная практика: программа дает инструменты для ведения индивидуального приема, разработки авторских коррекционных методик и профессионального консультирования родителей по вопросам развития ребенка."], "abilities": []}', NULL, 1, @start_order + 9);
INSERT IGNORE INTO courses (title, slug, description, target_audience_text, course_group, hours, program_type, learning_format, price, modules_json, outcomes_json, federal_registry_info, is_active, display_order) VALUES ('Педагогическое образование. Химия в условиях реализации ФГОС ООО, СОО', 'pedagogicheskoe-obrazovanie-himiya-v-usloviyah-realizatsii-fgos-ooo-soo', 'Программа для учителей химии научит грамотно планировать и проводить учебные занятия, разрабатывать рабочую программу по предмету, а также применять современные образовательные технологии.', NULL, 'Школа', 520, 'pp', 'заочная с применением дистанционных образовательных технологий', 47700, '[{"number": 1, "title": "Педагогические технологии в современной школе"}, {"number": 2, "title": "Введение и реализация ФГОС ООО в общеобразовательных организациях"}, {"number": 3, "title": "Введение и реализация ФГОС среднего общего образования в общеобразовательных организациях"}, {"number": 4, "title": "Содержание и организация обучения химии в условиях реализации ФГОС"}]', '{"knowledge": [], "skills": ["Работа учителем химии в школе: вы будете вести уроки и практические занятия в лаборатории, организовывать внеурочную деятельность, развивать у школьников исследовательские навыки, умение работать с реактивами и оборудованием, формировать интерес к науке, заниматься методической деятельностью, поддерживать конструктивное взаимодействие с родителями, коллегами и администрацией.\\n\\nРабота в государственных и частных учреждениях дополнительного образования: вы сможете разрабатывать авторские программы, вести кружки по химии, организовывать научно-исследовательскую деятельность.\\n\\nЧастная практика (репетиторство): в сферу вашей деятельности будет входить подготовка учеников к итоговой аттестации (ВПР, ОГЭ, ЕГЭ) и олимпиадам, помощь в освоении сложных тем и углубленном изучении химии, сопровождение научно-исследовательских работ."], "abilities": []}', NULL, 1, @start_order + 10);
INSERT IGNORE INTO courses (title, slug, description, target_audience_text, course_group, hours, program_type, learning_format, price, modules_json, outcomes_json, federal_registry_info, is_active, display_order) VALUES ('Педагогическое образование. Информатика в условиях реализации ФГОС ООО, СОО', 'pedagogicheskoe-obrazovanie-informatika-v-usloviyah-realizatsii-fgos-ooo-soo', 'Программа для тех, кто хочет обучать школьников грамотно использовать современные технологии, постоянно изучать новое, планировать и проводить учебные занятия.', NULL, 'Школа', 520, 'pp', 'заочная с применением дистанционных образовательных технологий', 47700, '[{"number": 1, "title": "Педагогические технологии в современной школе"}, {"number": 2, "title": "Введение и реализация ФГОС ООО в общеобразовательных организациях"}, {"number": 3, "title": "Введение и реализация ФГОС среднего общего образования в общеобразовательных организациях"}, {"number": 4, "title": "Содержание и организация обучения информатике в условиях реализации ФГОС"}, {"number": 5, "title": "Преподавание предмета «Информатика» в центре образования «Точка роста»"}]', '{"knowledge": [], "skills": ["Работа учителем информатики в школе: вы будете вести уроки и практические занятия, обучать основам программирования, работе с алгоритмами и онлайн-инструментами, готовить методические материалы, участвовать в школьных ИТ-проектах, поддерживать продуктивное взаимодействие с родителями, коллегами и администрацией.\\n\\nРабота в государственных и частных учреждениях дополнительного образования: вы сможете разрабатывать и внедрять авторские программы, вести кружки по робототехнике, программированию и кибербезопасности, готовить учащихся к конкурсам и конференциям.\\n\\nЧастная практика (репетиторство): в сферу вашей деятельности будет входить подготовка учеников к итоговой аттестации (ВПР, ОГЭ, ЕГЭ), олимпиадам и ИТ-соревнованиям, сопровождение проектной деятельности, консультирование по созданию приложений, сайтов или цифровых решений."], "abilities": []}', NULL, 1, @start_order + 11);
INSERT IGNORE INTO courses (title, slug, description, target_audience_text, course_group, hours, program_type, learning_format, price, modules_json, outcomes_json, federal_registry_info, is_active, display_order) VALUES ('Специальное (дефектологическое) образование. Работа учителя-дефектолога с детьми с нарушениями зрения дошкольного и школьного возрастов (профиль: нарушения зрения)', 'spetsialnoe-defektologicheskoe-obrazovanie-rabota-uchitelya-defektologa-s-detmi-s-narusheniyami-zreniya-doshkolnogo-i-shkolnogo-vozrastov-profil-narusheniya-zreniya', 'После обучения вы получите диплом о профессиональной переподготовке «учитель-дефектолог (профиль: нарушения зрения)» и сможете осуществить свою мечту — помогать детям с нарушениями зрения, улучшая их качество жизни.', 'Начинающие специалисты\nКурс для начинающих специалистов, которые работают с детьми с нарушениями зрения в качестве дефектологов, педагогов, воспитателей, тьюторов. Курс поможет систематизировать коррекционную работу с детьми с нарушениями зрения.', 'Дошкольное образование', 520, 'pp', 'заочная с применением дистанционных образовательных технологий', 25800, '[{"number": 1, "title": "Медико-биологические основы дефектологии"}, {"number": 2, "title": "Основы нейропсихологии в работе учителя-дефектолога"}, {"number": 3, "title": "Основы специальной педагогики и психологии"}, {"number": 4, "title": "Возрастная педагогика и психология"}, {"number": 5, "title": "Основы логопедии"}, {"number": 6, "title": "Патопсихология"}, {"number": 7, "title": "Инклюзивное и интегративное образование"}, {"number": 8, "title": "Работа с детьми с нарушениями зрения"}, {"number": 9, "title": "Работа с детьми с комплексными расстройствами"}, {"number": 10, "title": "Взаимодействие учителя-дефектолога с родителями"}, {"number": 11, "title": "Работа учителя-дефектолога в образовательных учреждениях"}, {"number": 12, "title": "Взаимодействие специалистов по сопровождению ребенка с ОВЗ, ребенка-инвалида"}, {"number": 13, "title": "Профилактика синдрома эмоционального выгорания"}, {"number": 14, "title": "Цифровые компетенции современного педагога"}]', '{"knowledge": [], "skills": ["Образовательные организации: вы сможете работать по востребованной специальности в государственных и частных образовательных организациях (ДОУ компенсирующей направленности, школы для детей с ОВЗ, ресурсные классы, инклюзивные школы).\\n\\nЧастная практика: открытие частного кабинета коррекционно-развивающих занятий для детей с нарушениями зрения."], "abilities": []}', NULL, 1, @start_order + 12);
INSERT IGNORE INTO courses (title, slug, description, target_audience_text, course_group, hours, program_type, learning_format, price, modules_json, outcomes_json, federal_registry_info, is_active, display_order) VALUES ('Педагогическое образование. Биология в условиях реализации ФГОС ООО, СОО', 'pedagogicheskoe-obrazovanie-biologiya-v-usloviyah-realizatsii-fgos-ooo-soo', 'Программа для учителей биологии научит грамотно планировать и проводить учебные занятия, разрабатывать рабочую программу по предмету, а также применять современные образовательные технологии.', NULL, 'Школа', 520, 'pp', 'заочная с применением дистанционных образовательных технологий', 47700, '[{"number": 1, "title": "Педагогические технологии в современной школе"}, {"number": 2, "title": "Введение и реализация ФГОС ООО в общеобразовательных организациях"}, {"number": 3, "title": "Введение и реализация ФГОС среднего общего образования в общеобразовательных организациях"}, {"number": 4, "title": "Содержание и организация обучения биологии в условиях реализации ФГОС"}]', '{"knowledge": [], "skills": ["Работа учителем биологии в школе: вы будете проводить уроки и внеурочные занятия, развивать познавательную деятельность учеников — в тематических кружках, практикумах, экологических проектах, заниматься методической деятельностью по предмету, взаимодействовать с родителями, коллегами и администрацией.\\n\\nРабота в государственных и частных учреждениях дополнительного образования: вы сможете разрабатывать и реализовывать свобственные программы по биологии, организовывать занятиях в кружках, устраивать лабораторные и полевые занятия — для более углубленного изучения предмета учениками.\\n\\nЧастная практика (репетиторство): индивидуальная работа по поготовке к итоговым аттестациям (ВПР, ОГЭ, ЕГЭ) и олимпиадам, помощь ученикам в освоении сложных тем, сопровождение научно-исследовательских работ. Вы сможете также развиваться как участник просветительских проектов и научных фестивалей, разрабатывать образовательный контент для научно-популярных платформ."], "abilities": []}', NULL, 1, @start_order + 13);
INSERT IGNORE INTO courses (title, slug, description, target_audience_text, course_group, hours, program_type, learning_format, price, modules_json, outcomes_json, federal_registry_info, is_active, display_order) VALUES ('Педагогическое образование. Физическая культура в условиях реализации ФГОС ООО, СОО', 'pedagogicheskoe-obrazovanie-fizicheskaya-kultura-v-usloviyah-realizatsii-fgos-ooo-soo', 'Программа для учителей физической культуры научит грамотно планировать и проводить учебные занятия, организовывать спортивно-массовую и физкультурно-оздоровительную работу.', NULL, 'Школа', 520, 'pp', 'заочная с применением дистанционных образовательных технологий', 47700, '[{"number": 1, "title": "Педагогические технологии в современной школе"}, {"number": 2, "title": "Введение и реализация обновленного ФГОС ООО в общеобразовательных организациях"}, {"number": 3, "title": "Введение и реализация обновленного ФГОС среднего общего образования в общеобразовательных организациях"}]', '{"knowledge": [], "skills": ["Работа учителем физической культуры в школе: вы будете проводить уроки, организовывать внеурочную деятельность, развивать у учеников силу, выносливость, координацию и командный дух, формировать навыки здорового образа жизни. В сферу вашей деятельности также будет входить подготовка методических материалов и поддержка продуктивного взаимодействия с родителями, коллегами и администрацией.\\n\\nРабота в государственных и частных учреждениях дополнительного образования: вы сможете разрабатывать программы дополнительного образования в сфере физической культуры и спорта, вести спортивные секции, готовить команды к соревнованиям, организовывать спортивные лагеря."], "abilities": []}', NULL, 1, @start_order + 14);
INSERT IGNORE INTO courses (title, slug, description, target_audience_text, course_group, hours, program_type, learning_format, price, modules_json, outcomes_json, federal_registry_info, is_active, display_order) VALUES ('Педагогическое образование. Воспитатель группы продленного дня', 'pedagogicheskoe-obrazovanie-vospitatel-gruppy-prodlennogo-dnya', 'Программа позволит по-новому взглянуть на работу группы продленного дня.', NULL, 'Дошкольное образование', 250, 'pp', 'заочная с применением дистанционных образовательных технологий', 36300, '[{"number": 1, "title": "Педагогика как наука и область практической деятельности. Общие основы педагогического процесса"}, {"number": 2, "title": "Воспитательный процесс. Особенности содержания и организации воспитательного процесса на современном этапе"}, {"number": 3, "title": "Теория обучения (дидактика). Особенности содержания и организации дидактического процесса на современном этапе"}, {"number": 4, "title": "Теоретические основы психологии"}, {"number": 5, "title": "Федеральный государственный образовательный стандарт начального общего образования"}, {"number": 6, "title": "Федеральный государственный образовательный стандарт основного общего образования"}, {"number": 7, "title": "Организация внеурочной деятельности в ГПД"}, {"number": 8, "title": "Специфика реализации внеурочной деятельности ГПД"}, {"number": 9, "title": "Взаимодействие с родителями в рамках ГПД"}]', '{"knowledge": [], "skills": ["Работа воспитателем группы продленного дня в школах и частных детских центрах: вы будете сопровождать детей после уроков, помогать выполнять домашние задания, организовывать развивающие игры, творческие и спортивные занятия, создавать условия для отдыха и общения, формировать навыки самостоятельности и ответственности.\\n\\nВедение частной практики: в сферу вашей деятельности будет входить организация присмотра за детьми в каникулярное время, проведение досуговых мероприятий, создание условий для качественного отдыха, общения и развития творческих способностей."], "abilities": []}', NULL, 1, @start_order + 15);
INSERT IGNORE INTO courses (title, slug, description, target_audience_text, course_group, hours, program_type, learning_format, price, modules_json, outcomes_json, federal_registry_info, is_active, display_order) VALUES ('Логопедия. Работа с обучающимися с нарушениями речи и коммуникации с дополнительной специализацией в области дошкольной дефектологии', 'logopediya-rabota-s-obuchayuschimisya-s-narusheniyami-rechi-i-kommunikatsii-s-dopolnitelnoy-spetsializatsiey-v-oblasti-doshkolnoy-defektologii', 'Вы станете успешным специалистом, который получает двойную квалификацию в области логопедии и дошкольной дефектологии. Сможете работать как с нарушениями речи, так и детьми ОВЗ, обеспечивая комплексную поддержку ребенка.', 'Начинающие логопеды и дефектологи\nКурс подойдет специалистам, желающим получить актуальные знания и навыки для уверенного старта в профессии.\n\nОпытные специалисты\nВы обновите свой инструментарий современными методами нейронаук и доказательной педагогики для работы с детьми с ОВЗ, научитесь этично взаимодействовать с семьями, избегать профессионального выгорания, а также укрепите свои базовые знания в области логопедии и дефектологии.\n\nПедагоги (воспитатели, учителя, психологи)\nВы получите востребованную профессию и будете помогать детям с ОВЗ.', 'Специальное образование', 1300, 'pp', 'заочная с применением дистанционных образовательных технологий', 128000, '[{"number": 1, "title": "Основы специальной педагогики и психологии"}, {"number": 2, "title": "Психология развития и возрастная психология"}, {"number": 3, "title": "Введение в логопедию"}, {"number": 4, "title": "Медико-биологические основы логопедии"}, {"number": 5, "title": "Классификации речевых нарушений"}, {"number": 6, "title": "Фонетико-фонематическое недоразвитие (ФФНР)"}, {"number": 7, "title": "Дислалия"}, {"number": 8, "title": "Дизартрия"}, {"number": 9, "title": "Алалия и общее недоразвитие речи (ОНР)"}, {"number": 10, "title": "Ринолалия"}, {"number": 11, "title": "Нарушения голоса"}, {"number": 12, "title": "Афазия"}, {"number": 13, "title": "Нарушение темпо-ритмической организации: заикание, тахилалия и брадилалия"}, {"number": 14, "title": "Нарушения письменной речи: дисграфия, дислексия, дизорфография"}, {"number": 15, "title": "Современный подход к классификации речевых нарушений"}, {"number": 16, "title": "Логопедические технологии коррекции речевых нарушений"}, {"number": 17, "title": "Работа логопеда в цифровом пространстве"}, {"number": 18, "title": "Работа логопеда в ДОУ"}, {"number": 19, "title": "Работа логопеда в школе"}, {"number": 20, "title": "Медико-биологические основы дефектологии"}, {"number": 21, "title": "Основы нейропсихологии в работе учителя-дефектолога"}, {"number": 22, "title": "Клинические основы психофизических расстройств у детей"}, {"number": 23, "title": "Основы патопсихологии"}, {"number": 24, "title": "Работа с детьми с нарушениями слуха"}, {"number": 25, "title": "Работа с детьми с нарушениями зрения"}, {"number": 26, "title": "Работа с детьми с НОДА"}, {"number": 27, "title": "Работа с детьми с ЗПР"}, {"number": 28, "title": "Работа с детьми с ИН (УО)"}, {"number": 29, "title": "Работа с детьми с РАС"}, {"number": 30, "title": "Работа с детьми с комплексными расстройствами"}, {"number": 31, "title": "Работа с детьми с ТМНР"}, {"number": 32, "title": "Психолого-педагогические технологии в работе дефектолога"}, {"number": 33, "title": "Нормативно-правовая база работы дефектолога"}, {"number": 34, "title": "Взаимодействие специалистов по сопровождению ребенка с ОВЗ"}, {"number": 35, "title": "Взаимодействие с родителями"}, {"number": 36, "title": "Профилактика синдрома эмоционального выгорания"}, {"number": 37, "title": "Цифровые компетенции современного педагога"}]', '{"knowledge": [], "skills": ["Детский сад и школа: выпускник сможет реализовывать адаптированные программы (ФАОП), проводить диагностику и выстраивать логопедическую работу с детьми с нарушениями речевого развития.\\n\\nДетский сад: выпускник сможет реализовывать адаптированные программы (ФАОП), проводить диагностику и выстраивать дефектологическую работу с детьми с ОВЗ. Реабилитационные центры и ПМПК: специалист готов к работе в мультидисциплинарной команде, где будет проводить сложную дифференциальную диагностику, составлять заключения и координировать сопровождение детей с тяжелыми нарушениями.\\n\\nЧастная практика: программа дает инструменты для ведения индивидуального приема, разработки авторских коррекционных методик и профессионального консультирования родителей по вопросам развития ребенка."], "abilities": []}', NULL, 1, @start_order + 16);
INSERT IGNORE INTO courses (title, slug, description, target_audience_text, course_group, hours, program_type, learning_format, price, modules_json, outcomes_json, federal_registry_info, is_active, display_order) VALUES ('Специальное (дефектологическое) образование. Работа учителя-дефектолога с детьми с умственной отсталостью (интеллектуальными нарушениями), с тяжелыми и множественными нарушениями развития (ТМНР) дошкольного и школьного возрастов (профиль: интеллектуальные нарушения)', 'spetsialnoe-defektologicheskoe-obrazovanie-rabota-uchitelya-defektologa-s-detmi-s-umstvennoy-otstalostyu-intellektualnymi-narusheniyami-s-tyazhelymi-i-mnozhestvennymi-narusheniyami-razvitiya', 'Вы станете востребованным дефектологом, владеющим современными методами диагностики и коррекции интеллектуальных нарушений у детей дошкольного и школьного возраста.', 'Дефектолог\nКурс предназначен как для начинающих дефектологов, желающих получить актуальные знания и навыки для уверенного старта в профессии, так и опытным специалистам, стремящимся обновить свой инструментарий методами нейронаук и доказательной педагогики для работы с детьми с ИН и ТМНР.', 'Специальное образование', 520, 'pp', 'заочная с применением дистанционных образовательных технологий', 25800, '[{"number": 1, "title": "Медико-биологические основы дефектологии"}, {"number": 2, "title": "Основы нейропсихологии в работе учителя-дефектолога"}, {"number": 3, "title": "Основы специальной педагогики и психологии"}, {"number": 4, "title": "Возрастная педагогика и психология"}, {"number": 5, "title": "Основы логопедии"}, {"number": 6, "title": "Основы патопсихологии"}, {"number": 7, "title": "Инклюзивное и интегративное образование"}, {"number": 8, "title": "Работа с детьми с ИН"}, {"number": 9, "title": "Работа с детьми с комплексными расстройствами"}, {"number": 10, "title": "Работа с детьми с ТМНР"}, {"number": 11, "title": "Взаимодействие учителя-дефектолога с родителями"}, {"number": 12, "title": "Работа учителя-дефектолога в образовательных учреждениях"}, {"number": 13, "title": "Взаимодействие специалистов по сопровождению ребенка с ОВЗ, ребенка-инвалида"}, {"number": 14, "title": "Профилактика синдрома эмоционального выгорания"}, {"number": 15, "title": "Цифровые компетенции современного педагога"}]', '{"knowledge": [], "skills": ["Детский сад и школа: выпускник сможет реализовывать адаптированные программы (ФАОП), проводить диагностику и выстраивать инклюзивное обучение детей с ИН и ТМНР в рамках государственных образовательных учреждений.\\n\\nРеабилитационные центры и ПМПК: специалист готов к работе в мультидисциплинарной команде, где будет проводить сложную дифференциальную диагностику, составлять СИПР и координировать сопровождение детей с тяжелыми нарушениями.\\n\\nЧастная практика: программа дает инструменты для ведения индивидуального приема, разработки авторских коррекционных методик и профессионального консультирования родителей по вопросам развития ребенка."], "abilities": []}', NULL, 1, @start_order + 17);
